    private static JsonNode run(ObjectNode model,DecisionInputCapturePort.Frozen f){ArrayNode modules=SrppReportModuleCalculator.calculateShared(f,SrppReportFixtures.AUTHORITY.decision().policy(),model,SrppReportFixtures.supported(),f.input().path("sources"));for(JsonNode m:modules)if(m.path("moduleId").asText().equals("STRATEGIC_BUY_GATES"))return m;throw new AssertionError();}
    private static JsonNode leg(JsonNode module,String code){for(JsonNode l:module.path("data").path("legs"))if(code.equals(l.path("symbol").asText()))return l;throw new AssertionError();}
    @Test void completeSourcesProducePositiveMediumCeilingsIncluding00881Above38(){ObjectNode m=model();var f=frame(m,s->{});JsonNode module=run(m,f);for(String code:List.of("0050","00881")){JsonNode l=leg(module,code);assertThat(l.path("status").asText()).isEqualTo("ACTIONABLE_FOR_REPORT");assertThat(l.path("lots").asInt()).isPositive();assertThat(l.path("receipts")).hasSize(14);assertThat(l.path("blockingReasons")).isEmpty();}assertThat(n(leg(module,"00881").path("limitPrice").asText())).isGreaterThan(n("38"));}
    @Test void targetSelectionUsesOriginalMarketFactsBeforeOrderFundingAndNeverAuthorizesTrade(){ObjectNode m=model();var f=frame(m,s->{((ObjectNode)s.path("topup-state")).put("verified",false).put("status","UNAVAILABLE");});var t=SrppReportMediumDipCalculator.targets(f,m);assertThat(t.ready()).isTrue();assertThat(t.selected()).isEqualTo("00881");assertThat(t.adjustment()).isCloseTo(SrppReserveAllocation.project(m,f.facts().totalAssets(),DAY).delta(),within(n(".000001")));assertThat(leg(run(m,f),"00881").path("lots").asInt()).isZero();}
