    private static JsonNode directAssets(JsonNode source){
        ObjectNode result=source.deepCopy();java.util.Set<String> numeric=Set.of("amount","originalAmount","annualInterestRate","estimatedAnnualInterest","shares","currentValue","liveValue","currentPrice","exchangeRate","totalDeposit","totalFundValue","totalStockValue","totalAssets","liveTotalAssets","liveStockValue","price","previousClose","openPrice","highPrice","lowPrice","buyPrice","sellPrice","volume","size","bidPrice","askPrice","bidVolumeLots","askVolumeLots");
        convertDirect(result,numeric);return result;
    }
    private static void convertDirect(JsonNode value,Set<String> numeric){if(value.isArray()){value.forEach(v->convertDirect(v,numeric));return;}if(!value.isObject())return;ObjectNode o=(ObjectNode)value;List<String> keys=new ArrayList<>();o.fieldNames().forEachRemaining(keys::add);for(String key:keys){JsonNode v=o.path(key);if(numeric.contains(key)&&v.isTextual())o.set(key,F.numberNode(new BigDecimal(v.asText())));else convertDirect(v,numeric);}}

